          "判断这段时间有没有价值，也不宜只数写了多少字。更具体的结果可以是：找出了一个原先含混的前提，删除一条没有证据的推断，或者形成一个可以尝试的新方案。这样才能区分思考推进与单纯堆积文字。这个评价办法属于本站建议。"
