  "tim-marie-forleo-2017": {
    "sections": [
      {
        "heading": "先把写作过程安排得足够稳定",
        "kind": "source",
        "paragraphs": [
          "Marie Forleo 询问 Tim 的写作变化。他重视稳定的日常安排，减少临时决定带来的消耗，并区分适合自己的综合写作时段与适合做资料、联络工作的时段。访谈中的场所和运动是其个人安排，不是写作必须具备的条件。"
        ]
      },
      {
        "heading": "章节可以成为独立模块",
        "kind": "source",
        "paragraphs": [
          "Tim 把章节按独立专题文章处理，让每章具有足够背景和完整价值。这样卡在某章时仍能写另一章，读者也能跳读。他还提醒自己在书稿完成前先集中写作，避免用更有吸引力的营销计划逃开正文。"
        ]
      },
      {
        "heading": "具体读者让表达更容易",
        "kind": "source",
        "paragraphs": [
          "谈及第一本书，他回忆曾把内容写成给两位朋友的邮件，以熟悉的对象帮助自己找到语气。试图让所有人都喜欢，可能削弱作品的鲜明程度。这个入口不表示作品只能被最初设想的人阅读。"
        ]
      },
      {
        "heading": "编辑分析｜先交付一章能单独成立的内容",
        "kind": "analysis",
        "paragraphs": [
          "准备长文或课程时，可以先选一个真实问题，说明读者处境、给出必要背景、展示一个完整例子，最后指出适用边界。这个模块即使暂时没有前后章节，也应当让读者得到具体帮助。这里的制作顺序是本站建议。独立模块能够减少写作阻塞，但后期仍需统一术语、检查重复和衔接；模块化是降低起草难度的方法，并不替代整体编辑。"
        ]
      }
    ],
    "takeaway": "本站提炼：减少写作时的临时决定，让章节独立成立，再把内容写给一个可以想象的具体读者。",
    "references": [
      {
        "title": "MarieTV · Marie Forleo｜原始节目页面",
        "url": "https://www.marieforleo.com/blog/tim-ferriss-tribe-of-mentors"
      }
    ]
  },
  "tim-google-chef-2012": {
    "sections": [
      {
        "heading": "用烹饪展示元学习",
        "kind": "source",
        "paragraphs": [
          "Tim 在 Google 介绍《四小时厨师》。书以烹饪为具体学习场景，同时讨论怎样学习新的能力；从元学习到家庭厨房、野外、科学与专业场景，内容安排把厨房问题与更广的技能习得连接起来。"
        ]
      },
      {
        "heading": "拆开、选择、排序",
        "kind": "source",
        "paragraphs": [
          "演讲中的学习方法强调拆解一项技能、挑选影响较大的部分，并寻找适合初学者的练习顺序。顺序重要，是因为传统教学的开始位置未必适合每个人；学习者需要知道自己先练什么，怎样看见进展。"
        ]
      },
      {
        "heading": "让练习有实际约束",
        "kind": "source",
        "paragraphs": [
          "方法还涉及为行动建立约束和承担成本，而不只收集更多资料。重点是把模糊的学会转换为可以安排和检验的练习。本站据演讲与内容索引整理方法，不复现整本书的食谱、实验或操作细节。"
        ]
      },
      {
        "heading": "编辑分析｜用一个完成标准限制学习范围",
        "kind": "analysis",
        "paragraphs": [
          "若想学做演示文稿，可以先把目标设为讲清一个五分钟方案，再拆成问题、证据、选择和下一步，而不是一次学习所有视觉效果。做出初稿后，请一位没有背景的同事复述方案，检查他遗漏的地方。这个例子是本站建议。这样练习顺序由使用场景决定，反馈也指向具体缺口；学习材料仍重要，但选择材料前先有完成标准，可以减少没有终点的收藏。"
        ]
      }
    ],
    "takeaway": "本站提炼：先明确要完成的场景，再决定技能拆分、练习顺序和反馈方式。",
    "references": [
      {
        "title": "Talks at Google｜原始节目页面",
        "url": "https://www.youtube.com/watch?v=gj3RskVvVLA"
      },
      {
        "title": "演讲内容索引",
        "url": "https://glasp.co/youtube/p/the-four-hour-chef-tim-ferriss-talks-at-google"
      }
    ]
  },
