  "elon-code-2016": {
    "sections": [
      {
        "heading": "把时间承诺放回2016年的现场",
        "kind": "source",
        "paragraphs": [
          "Kara Swisher与Walt Mossberg在Code 2016采访马斯克，主办方完整视频简介列出火星、单程任务与当时的到达时间预期。这些是那场访谈中的计划与判断，不是后续成果的核验报告。"
        ]
      },
      {
        "heading": "竞争、自动驾驶与AI开放性",
        "kind": "source",
        "paragraphs": [
          "对话还涉及电动车竞争、自动驾驶成为常态的设想，以及马斯克为什么希望更多人拥有使用AI的能力。不同主题连接了公司竞争与技术在社会中的分布，需分别考察其成立条件。"
        ]
      },
      {
        "heading": "编辑分析｜将路线图拆成可交付的阶段",
        "kind": "analysis",
        "paragraphs": [
          "阅读一项远期承诺时，可以先画依赖图：最终结果之前必须完成哪些步骤，哪些可以并行，哪些依赖外部条件。比如一个软件产品进入新市场，不只需要翻译界面，还可能需要客户支持、支付和本地流程。把每一步写清楚后，就能发现一句看似简单的时间承诺，实际上包含了多少尚未验证的假设。"
        ]
      },
      {
        "heading": "编辑分析｜记录预测，才能学习如何判断",
        "kind": "analysis",
        "paragraphs": [
          "为重要预测建立一张小卡片，写日期、具体结果、前置条件以及什么证据会让自己调整信心。隔一段时间再回看，检查是目标改变、路径改变，还是原本低估了某项困难。即使最终方向相近，也不要忽略时间和资源成本的差异。这种做法有助于从科技访谈中学习判断，而不是只收集后来实现的预言，或只用一次错期否定所有技术探索；两种选择都会漏掉真正值得研究的过程。"
        ]
      }
    ],
    "takeaway": "编辑提炼：远期承诺需要依赖图，历史预测需要有日期的复盘。",
    "references": [
      {
        "title": "Code Conference · Kara Swisher / Walt Mossberg · 原始资料",
        "url": "https://www.youtube.com/watch?v=wsixsRI-Sz4"
      }
    ]
  },
