  "julian-mfm-211": {
    "sections": [
      {
        "heading": "三种增长机制，分别改变什么",
        "kind": "source",
        "paragraphs": [
          "这场六十余分钟的对话依次讨论让客户容易做决定、降低操作摩擦、使产品使用自然产生曝光，以及自我偿付式漏斗。后半部分转向不固定发布节奏、社交平台简介和讲故事。",
          "它把增长从单纯购买流量，扩展到交易设计、使用流程和传播方式。节目标题带有强烈营销语气，内容应作为机制讨论阅读，不能理解成收益承诺。"
        ]
      },
      {
        "heading": "编辑分析：分享应当服务原来的任务",
        "kind": "analysis",
        "paragraphs": [
          "假设用户用一个工具生成项目报告，向同事发送报告本来就是任务的一部分。若接收者因此接触工具，传播与用户价值方向一致；如果必须先邀请三个人才能下载，分享便成了额外障碍。这两种设计，不能只用邀请数比较。",
          "先画出用户得到价值的过程，再找其中已有的协作或展示动作。观察接收者是否真正使用，而不只是打开链接。只有传播后仍获得价值，新增用户才可能继续带来下一轮使用。"
        ]
      },
      {
        "heading": "编辑分析：前端收入也有成本",
        "kind": "analysis",
        "paragraphs": [
          "低价产品能够带来收入和潜在客户，但仍要计算交付、退款、支付与后续服务成本。如果前端订单亏损，仅凭有人留下邮箱，不能证明整体获客已经回本。用一个独立小批次测试，跟踪后续购买，才能看出这条链路是否成立。",
          "发布频率同样要服务内容质量和受众预期。稳定产出与不定期发布各有适用条件，应比较长期有效询问和实际使用，而不是把某位创作者的节奏直接搬到自己的团队。"
        ]
      }
    ],
    "takeaway": "编辑提炼：增长机制要同时解释用户为什么行动、如何传播，以及每次行动的成本。",
    "practice": "原创编辑练习：选一个产品，标出用户首次得到价值、自然分享和首次付费的位置。检查其中哪一步存在不必要的等待或要求。",
    "references": [
      {
        "title": "MFM官方节目页与章节",
        "url": "https://www.mfmpod.com/211-with-julian-shapiro-the-3/"
      },
      {
        "title": "主办方完整视频",
        "url": "https://www.youtube.com/watch?v=sdKxzWniujU"
      }
    ]
  },
  "julian-lenny-2022": {
    "sections": [
      {
        "heading": "从产品使用过程里寻找分发",
        "kind": "source",
        "paragraphs": [
          "节目先讨论产品驱动获客的类别，再讨论产品曝光、用户生成内容和留存机制。后半段转向如何保持写作的新意、如何选择主题，以及创造力水龙头这一比喻。",
          "这些话题把产品设计与内容创作连在一起：一方面观察用户为何邀请别人，另一方面观察读者为何愿意继续读。对话并未把所有产品都归为同一种增长模型。"
        ]
      },
      {
        "heading": "编辑分析：区分邀请奖励与真实协作",
        "kind": "analysis",
        "paragraphs": [
          "在多人协作工具里，一位使用者邀请同事，是为了共同完成任务。与之相比，发优惠券换邀请，主要改变的是激励。前者能否发生，取决于任务是否确实需要别人参与；后者是否有效，还要检查奖励结束后用户会不会留下。",
          "留存也应区分持续价值和迁移障碍。一个用户积累了资料，不代表他一定满意。可以同时观察重复完成任务、主动推荐和退出反馈，避免把无法轻易离开误认作产品受到喜爱。"
        ]
      },
      {
        "heading": "编辑分析：给新意配一个可以理解的载体",
        "kind": "analysis",
        "paragraphs": [
          "创作时，可以先写下一个与常识不同、但你能解释的观察，再找一个具体场景承载它。例如，想说明功能多不等于好用，可以描写首次使用者面对十个入口却不知道先点哪里的瞬间。抽象判断于是变得能够检验。",
          "把初稿当作寻找想法的过程，而不是一次定稿的表演。先允许无效段落出现，再通过删改保留有解释力的部分。读者测试应询问哪里产生疑问、哪里值得记住，而不只问喜不喜欢。"
        ]
      }
    ],
    "takeaway": "编辑提炼：把传播设计进真实任务，把观点放进读者能够理解的情境。",
    "practice": "原创编辑练习：写一个一百字观察，请两位读者标出最想追问的一句，再围绕那个问题补充证据或例子。",
    "references": [
      {
        "title": "Lenny官方节目页、转录与章节",
        "url": "https://www.lennysnewsletter.com/p/building-a-product-led-acquisition"
      }
    ]
  },
