      {
        "heading": "延伸理解（编辑分析）",
        "kind": "analysis",
        "paragraphs": [
          "判断一个社群，可以观察成员怎样形成共同语言、如何持续贡献，以及付费是否损害原有体验。不要只看外部曝光；成员是否愿意留下、能否创造新内容，往往更能解释文化能否长期存在。"
        ]
      }
